-- ============================================================
-- The Dev Agency — Works/Projects CMS schema
-- Run this once in Supabase: SQL Editor → New Query → paste all
-- of this → Run.
--
-- Safe to re-run: every statement is guarded so running it twice
-- won't error out or duplicate data.
-- ============================================================

-- ── EXTENSIONS ──
create extension if not exists "pgcrypto"; -- gives us gen_random_uuid()

-- ── CATEGORIES ──
create table if not exists public.categories (
  id           uuid primary key default gen_random_uuid(),
  name         text not null,
  slug         text not null unique,
  description  text,
  sort_order   integer not null default 0,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

-- ── PROJECTS ──
create table if not exists public.projects (
  id            uuid primary key default gen_random_uuid(),
  category_id   uuid references public.categories(id) on delete set null,
  title         text not null,
  slug          text not null unique,
  tag           text,                          -- short label shown on the card, e.g. "E-Commerce"
  description   text,
  thumbnail_url text,
  gallery       jsonb not null default '[]'::jsonb,   -- array of image URLs
  external_url  text,                          -- link to the live project, if any
  client_name   text,
  project_date  date,
  technologies  jsonb not null default '[]'::jsonb,   -- array of strings
  tags          jsonb not null default '[]'::jsonb,   -- array of strings
  status        text not null default 'published' check (status in ('draft','published')),
  featured      boolean not null default false,
  sort_order    integer not null default 0,
  extra         jsonb not null default '{}'::jsonb,   -- open-ended bucket for future fields
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create index if not exists projects_category_id_idx on public.projects(category_id);
create index if not exists projects_status_idx on public.projects(status);

-- ── keep updated_at fresh ──
create or replace function public.set_updated_at()
returns trigger as $$
begin
  new.updated_at = now();
  return new;
end;
$$ language plpgsql;

drop trigger if exists trg_categories_updated_at on public.categories;
create trigger trg_categories_updated_at
  before update on public.categories
  for each row execute function public.set_updated_at();

drop trigger if exists trg_projects_updated_at on public.projects;
create trigger trg_projects_updated_at
  before update on public.projects
  for each row execute function public.set_updated_at();

-- ============================================================
-- ROW LEVEL SECURITY
-- Public visitors (anon key) may only READ published content.
-- Only a signed-in admin (authenticated via Supabase Auth) may
-- create, edit, delete, or see draft projects.
-- ============================================================

alter table public.categories enable row level security;
alter table public.projects   enable row level security;

drop policy if exists "categories are publicly readable" on public.categories;
create policy "categories are publicly readable"
  on public.categories for select
  to anon, authenticated
  using (true);

drop policy if exists "authenticated users manage categories" on public.categories;
create policy "authenticated users manage categories"
  on public.categories for all
  to authenticated
  using (true)
  with check (true);

drop policy if exists "published projects are publicly readable" on public.projects;
create policy "published projects are publicly readable"
  on public.projects for select
  to anon
  using (status = 'published');

drop policy if exists "authenticated users read all projects" on public.projects;
create policy "authenticated users read all projects"
  on public.projects for select
  to authenticated
  using (true);

drop policy if exists "authenticated users manage projects" on public.projects;
create policy "authenticated users manage projects"
  on public.projects for insert
  to authenticated
  with check (true);

drop policy if exists "authenticated users update projects" on public.projects;
create policy "authenticated users update projects"
  on public.projects for update
  to authenticated
  using (true)
  with check (true);

drop policy if exists "authenticated users delete projects" on public.projects;
create policy "authenticated users delete projects"
  on public.projects for delete
  to authenticated
  using (true);

-- ============================================================
-- STORAGE — bucket for project thumbnails / gallery images
-- ============================================================

insert into storage.buckets (id, name, public)
values ('project-images', 'project-images', true)
on conflict (id) do nothing;

drop policy if exists "project images are publicly readable" on storage.objects;
create policy "project images are publicly readable"
  on storage.objects for select
  to anon, authenticated
  using (bucket_id = 'project-images');

drop policy if exists "authenticated users upload project images" on storage.objects;
create policy "authenticated users upload project images"
  on storage.objects for insert
  to authenticated
  with check (bucket_id = 'project-images');

drop policy if exists "authenticated users update project images" on storage.objects;
create policy "authenticated users update project images"
  on storage.objects for update
  to authenticated
  using (bucket_id = 'project-images');

drop policy if exists "authenticated users delete project images" on storage.objects;
create policy "authenticated users delete project images"
  on storage.objects for delete
  to authenticated
  using (bucket_id = 'project-images');

